def normalize(value, fold):
    """Normalize a string for distance calculation.

    If *fold* is truthy, perform a Unicode casefold which is more aggressive
    than ``str.lower`` and suitable for case‑insensitive matching. Otherwise
    return the original value unchanged.
    """
    if fold:
        # ``casefold`` handles locale‑independent case folding, e.g. "ß" → "ss"
        return value.casefold()
    return value

